export function getCuratedCourses(): CuratedCourse[] {
  return CURATED_COURSES;
}

export function getFeaturedPreviewCourses(): CuratedCourse[] {
  return CURATED_COURSES.filter(c => c.featured);
}

export function getCourseById(id: string): CuratedCourse | undefined {
  return CURATED_COURSES.find(c => c.id === id);
}

export function getCourseByPlaylistId(playlistId: string): CuratedCourse | undefined {
  return CURATED_COURSES.find(c => c.ytPlaylistId === playlistId);
}
